public String minWindow(String s, String t) {
    if (s.length() < t.length()) return "";
    Map<Character, Integer> need = new HashMap<>();
    for (char c : t.toCharArray()) need.merge(c, 1, Integer::sum);
    int bestLen = Integer.MAX_VALUE, bestStart = -1;
    for (int i = 0; i < s.length(); i++) {
        Map<Character, Integer> have = new HashMap<>();
        for (int j = i; j < s.length(); j++) {
            have.merge(s.charAt(j), 1, Integer::sum);
            if (covers(have, need) && j - i + 1 < bestLen) {
                bestLen = j - i + 1;
                bestStart = i;
                break;
            }
        }
    }
    return bestStart == -1 ? "" : s.substring(bestStart, bestStart + bestLen);
}

private boolean covers(Map<Character, Integer> have, Map<Character, Integer> need) {
    for (Map.Entry<Character, Integer> e : need.entrySet()) {
        if (have.getOrDefault(e.getKey(), 0) < e.getValue()) return false;
    }
    return true;
}

