    from collections import Counter
    if len(s) < len(t):
        return ""
    need = Counter(t)
    best_len, best_start = float('inf'), -1
    for i in range(len(s)):
        have = Counter()
        for j in range(i, len(s)):
            have[s[j]] += 1
            if all(have[c] >= need[c] for c in need) and j - i + 1 < best_len:
                best_len, best_start = j - i + 1, i
                break
    return "" if best_start == -1 else s[best_start:best_start + best_len]

